<template><section class="space-y-6"><SectionHeader title="Лиды" text="CRM-воронка и список обращений с сайта." /><div class="card overflow-hidden"><table class="min-w-full text-sm"><thead class="bg-slate-900 text-slate-400"><tr><th class="px-4 py-3 text-left">Имя</th><th class="px-4 py-3 text-left">Услуга</th><th class="px-4 py-3 text-left">Контакт</th><th class="px-4 py-3 text-left">Статус</th></tr></thead><tbody><tr v-for="lead in rows" :key="lead.id" class="border-t border-slate-800"><td class="px-4 py-3">{{ lead.name }}</td><td class="px-4 py-3">{{ lead.service }}</td><td class="px-4 py-3">{{ lead.phone || lead.email }}</td><td class="px-4 py-3">{{ lead.status }}</td></tr></tbody></table></div></section></template><script setup>import axios from "axios"; import { onMounted, ref } from "vue"; import SectionHeader from "../../components/SectionHeader.vue"; const rows = ref([]); onMounted(async () => { const res = await axios.get("/admin/api/leads"); rows.value = res.data.data || []; })</script>